// hashchain — append-only tamper-evident chain
// Hash: sha256

fn chain_create::(genesis_data) {
    let genesis = {"index": 0, "ts": @time_ms(), "data": genesis_data,
                    "prev": "0", "hash": "0"};
    genesis["hash"] = chain_hash(genesis);
    return {"blocks": [genesis]};
}

fn chain_hash::(block) {
    let payload = @str(block["index"]) + "|" + @str(block["ts"]) + "|" +
                  @json_encode(block["data"]) + "|" + block["prev"];
    return @sha256_hex(@bytes(payload));
}

fn chain_append::(chain, data) {
    let last = chain["blocks"][@len(chain["blocks"]) - 1];
    let block = {"index": @len(chain["blocks"]), "ts": @time_ms(),
                  "data": data, "prev": last["hash"], "hash": "0"};
    block["hash"] = chain_hash(block);
    @push(chain["blocks"], block);
    return block;
}

fn chain_verify::(chain) {
    let blocks = chain["blocks"];
    for i in @range(1, @len(blocks)) {
        let b = blocks[i];
        let prev = blocks[i - 1];
        if (b["prev"] != prev["hash"]) { return {"ok": false, "at": i, "reason": "prev mismatch"}; }
        if (chain_hash(b) != b["hash"]) { return {"ok": false, "at": i, "reason": "hash mismatch"}; }
    }
    return {"ok": true, "length": @len(blocks)};
}

fn chain_height::(chain) { return @len(chain["blocks"]); }

fn chain_get::(chain, idx) {
    if (idx < 0 || idx >= @len(chain["blocks"])) { return null; }
    return chain["blocks"][idx];
}

fn chain_save::(chain, path) { @write_text(path, @json_encode(chain)); return true; }
fn chain_load::(path) { return @json_decode(@read_text(path)); }

fn version::() { return "1.0.0"; }
